INSERT INTO `v1_c5c9e7baf6f737a2013613b47cd3d8fbbc001080460d85dd6fc67122cec71ffe` VALUES (1, "イベントでは、特別なストーリーをお楽しみいただけます。\n閲覧可能なストーリーを読むと、次のお話が解放されていきますよ。\nストーリーの閲覧によって達成されるミッションもあるのだとか。", 1, 1, 1011);
INSERT INTO `v1_c5c9e7baf6f737a2013613b47cd3d8fbbc001080460d85dd6fc67122cec71ffe` VALUES (2, "イベントクエストやボスバトルに挑戦してみましょう。ボスバトルは\n特定のイベントストーリーを閲覧するか、イベントクエスト・ボス画面で\n「解放する」を選択すると挑戦可能になりますよ。", 2, 1, 1021);
INSERT INTO `v1_c5c9e7baf6f737a2013613b47cd3d8fbbc001080460d85dd6fc67122cec71ffe` VALUES (2, "育成ミッションは、特定の条件を達成することで報酬が獲得できる\n期間限定のミッションでございます。ステップごとに設定された\nミッションを全て達成すると、次のステップに進めますよ。", 3, 1, 1031);
INSERT INTO `v1_c5c9e7baf6f737a2013613b47cd3d8fbbc001080460d85dd6fc67122cec71ffe` VALUES (4, "報酬交換では「イベント報酬券」と様々なアイテムを交換できます。\n目玉となるリセット対象報酬を引くことで、より多くのアイテムが\n獲得できる次のラインナップへと進めるそうです。", 4, 1, 1041);
INSERT INTO `v1_c5c9e7baf6f737a2013613b47cd3d8fbbc001080460d85dd6fc67122cec71ffe` VALUES (5, "ボスバトルには３種の難易度がございます。\n各難易度ごとにボスの強さやバトルの特徴が異なりますので、\n準備をしっかりして、気を引き締めて挑みましょう。", 5, 1, 1051);
INSERT INTO `v1_c5c9e7baf6f737a2013613b47cd3d8fbbc001080460d85dd6fc67122cec71ffe` VALUES (1, "イベントでは、特別なストーリーをお楽しみいただけます。\n閲覧可能なストーリーを読むと、次のお話が解放されていきますよ。", 1, 2, 2011);
INSERT INTO `v1_c5c9e7baf6f737a2013613b47cd3d8fbbc001080460d85dd6fc67122cec71ffe` VALUES (2, "イベントクエストやボスバトルに挑戦してみましょう。ボスバトルは\n特定のイベントストーリーを閲覧するか、イベントクエスト・ボス画面で\n「解放する」を選択すると挑戦可能になりますよ。", 2, 2, 2021);
INSERT INTO `v1_c5c9e7baf6f737a2013613b47cd3d8fbbc001080460d85dd6fc67122cec71ffe` VALUES (4, "報酬交換では「イベント報酬券」と様々なアイテムを交換できます。\n目玉となるリセット対象報酬を引くことで、より多くのアイテムが\n獲得できる次のラインナップへと進めるそうです。", 4, 2, 2041);
INSERT INTO `v1_c5c9e7baf6f737a2013613b47cd3d8fbbc001080460d85dd6fc67122cec71ffe` VALUES (5, "ボスバトルには２種の難易度がございます。\n各難易度ごとにボスの強さやバトルの特徴が異なりますので、\n準備をしっかりして、気を引き締めて挑みましょう。", 5, 2, 2051);
